/**
 * Crônicas de Obsidiana: um RPG tático com inventário profissional e campanha em três encontros.
 * A interface mantém a direção obsidiana/cobre e privilegia decisões claras durante cada turno.
 */
import {
  Archive, Backpack, Bolt, BookOpen, ChevronRight, CircleDot, Coins, Crosshair, Crown,
  Droplets, Eye, Feather, Flame, Gem, HeartPulse, History, Mountain, PackageOpen,
  MessageCircle, Palette, ScrollText, Shield, ShieldCheck, ShieldPlus, ShoppingBag, Sparkles, Sword, Target,
  Trophy, WandSparkles, X, Zap,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { trpc } from "@/lib/trpc";

type ClassId = "guardian" | "duelist" | "arcanist";
type OriginId = "vigil" | "wilds" | "archive";
type AppearanceId = "copper" | "moon" | "ember";
type BattleState = "active" | "victory" | "defeat";
type TurnOwner = "hero" | "enemy";
type CombatMotion = "idle" | "hero-weapon" | "hero-magic" | "enemy-attack" | "hero-guard";
type ItemCategory = "consumable" | "equipment" | "material";
type Rarity = "comum" | "raro" | "épico";
type Slot = "weapon" | "armor" | "relic";
type Effect = "health" | "mana" | "attack" | "guard" | "none";
type ItemId = "healing" | "mana" | "bomb" | "ward" | "watchblade" | "lorancloak" | "astralring" | "obsidian" | "goblinmark" | "greaterheal" | "moonward" | "starlance" | "mendercloak" | "ravenseal";

type Draft = { name: string; classId: ClassId; originId: OriginId; appearanceId: AppearanceId };
type Intent = { id: string; label: string; description: string; min: number; max: number; icon: typeof Sword };
type Item = { id: ItemId; name: string; description: string; lore: string; quantity: number; category: ItemCategory; rarity: Rarity; effect: Effect; value: number; effectValue?: number; slot?: Slot; bonus?: { force?: number; arcane?: number; defense?: number; guard?: number } };
type StoreItem = { id: ItemId; price: number; featured?: boolean };
type Encounter = { name: string; role: "mob" | "subboss" | "boss"; description: string; hp: number; portrait: string; attackPortrait: string; intents: Intent[]; xp: number; gold: number; reward: { id: ItemId; quantity: number; label: string } };
type Log = { id: number; actor: string; message: string; tone: "hero" | "enemy" | "system" };
type SavedGame = {
  draft: Draft; started: boolean; encounterIndex: number; hero: { hp: number; mana: number; xp: number; gold: number };
  enemyHp: number; battleState: BattleState; turn: TurnOwner; intentId: string; inventory: Item[];
  selectedId: ItemId; equipped: Partial<Record<Slot, ItemId>>; logs: Log[]; merchantLine: string;
};

const sessionStorageKey = "rpg-scplt-session";

const classes = [
  { id: "guardian" as const, name: "Guardião Rúnico", summary: "Muralha viva da expedição", desc: "Equilíbrio entre lâmina, proteção e magia inscrita.", icon: ShieldCheck, hp: 84, mana: 36, stats: [16, 13, 18, 14], basic: "Corte do bastião", special: "Investida rúnica", critical: .15, guard: .45, passive: "Guarda absorve 55%" },
  { id: "duelist" as const, name: "Duelista de Bruma", summary: "Velocidade antes da dúvida", desc: "Movimentos leves, golpes rápidos e precisão contra alvos marcados.", icon: Feather, hp: 72, mana: 42, stats: [14, 19, 15, 11], basic: "Estocada veloz", special: "Corte de bruma", critical: .30, guard: .56, passive: "Crítico ampliado" },
  { id: "arcanist" as const, name: "Tecelão Astral", summary: "O céu responde à sua voz", desc: "Canalização arcana intensa, com reserva de mana ampliada.", icon: Sparkles, hp: 66, mana: 56, stats: [11, 13, 22, 10], basic: "Estilhaço astral", special: "Lança rúnica", critical: .20, guard: .65, passive: "Mana elevada" },
];
const origins = [
  { id: "vigil" as const, name: "Ordem da Vigília", desc: "Juramentos de pedra, vigias e relíquias de fronteira.", icon: Crown },
  { id: "wilds" as const, name: "Ermos de Veyra", desc: "A trilha, o vento e os perigos antigos ensinaram a sobreviver.", icon: Mountain },
  { id: "archive" as const, name: "Arquivo de Aster", desc: "Mapas celestes e memórias proibidas compõem seu legado.", icon: ScrollText },
];
const appearances = [
  { id: "copper" as const, name: "Cobre de Vigília", desc: "Âmbar e bronze" },
  { id: "moon" as const, name: "Bruma Lunar", desc: "Prata e azul" },
  { id: "ember" as const, name: "Brasa Rubra", desc: "Carmesim e carvão" },
];
const portraits: Record<ClassId, string> = {
  guardian: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/wgGdGRGLDsGEynoL.png",
  duelist: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/RLJlxAViLYuzbfWo.png",
  arcanist: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/uIbtChMAIAYKHvZt.png",
};
const attackPortraits: Record<ClassId, string> = {
  guardian: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/iwohBnZZUkMWXfRa.png",
  duelist: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/xQXGrkCHbvdDkvaZ.png",
  arcanist: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/UWDmFzyRziMluVmd.png",
};
const goblinIntents: Intent[] = [
  { id: "slash", label: "Golpe serrilhado", description: "Ataque direto", min: 8, max: 12, icon: Sword },
  { id: "heavy", label: "Talho brutal", description: "Alto dano", min: 13, max: 17, icon: Flame },
  { id: "venom", label: "Lâmina envenenada", description: "Dano preciso", min: 10, max: 14, icon: Eye },
];
const encounters: Encounter[] = [
  { name: "Batedor Goblin", role: "mob", description: "Saques velozes e lâmina envenenada.", hp: 68, portrait: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/OjrvVBEJmQditTgF.png", attackPortrait: "https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/lnbtFNtTkJuCMdrA.png", intents: goblinIntents, xp: 85, gold: 30, reward: { id: "healing", quantity: 1, label: "1 Poção Rubra" } },
  { name: "Bruto das Fendas", role: "subboss", description: "Quebra defesas com o malho de ferro das cavernas.", hp: 94, portrait: "/manus-storage/cave-brute-portrait_94b5f056.png", attackPortrait: "/manus-storage/cave-brute-portrait_94b5f056.png", intents: [{ id: "maul", label: "Impacto de malho", description: "Golpe contundente", min: 9, max: 13, icon: Sword }, { id: "quake", label: "Ruptura sísmica", description: "Ataque pesado", min: 12, max: 16, icon: Flame }, { id: "charge", label: "Investida bruta", description: "Dano e pressão", min: 10, max: 14, icon: Eye }], xp: 155, gold: 62, reward: { id: "greaterheal", quantity: 1, label: "1 Elixir de Aurora" } },
  { name: "Vigia de Loran", role: "boss", description: "Sentinela ancestral que protege o núcleo das ruínas.", hp: 132, portrait: "/manus-storage/loran-warden-boss_f6b02375.png", attackPortrait: "/manus-storage/loran-warden-boss_f6b02375.png", intents: [{ id: "rune", label: "Corte da vigília", description: "Lâmina rúnica", min: 12, max: 16, icon: Sword }, { id: "judgment", label: "Julgamento de obsidiana", description: "Ataque devastador", min: 15, max: 20, icon: Flame }, { id: "mark", label: "Marca do cerco", description: "Golpe calculado", min: 13, max: 18, icon: Eye }], xp: 280, gold: 110, reward: { id: "astralring", quantity: 1, label: "Anel de Aster" } },
];
const inventorySeed: Item[] = [
  { id: "healing", name: "Poção Rubra", description: "Restaura 28 de vitalidade.", lore: "Um extrato de cinzas vermelhas selado em vidro escuro.", quantity: 2, category: "consumable", rarity: "comum", effect: "health", value: 18, effectValue: 28 },
  { id: "mana", name: "Essência Astral", description: "Restaura 16 de mana.", lore: "Partículas de luz fria preservadas por escribas do Arquivo.", quantity: 1, category: "consumable", rarity: "raro", effect: "mana", value: 28, effectValue: 16 },
  { id: "bomb", name: "Fogo Alquímico", description: "Causa 22 de dano direto.", lore: "Uma ampola instável que se rompe em brasas de mercúrio.", quantity: 1, category: "consumable", rarity: "raro", effect: "attack", value: 34, effectValue: 22 },
  { id: "ward", name: "Selo de Guarda", description: "Ativa uma guarda reforçada.", lore: "Um fragmento gravado com o juramento dos guardiões de Loran.", quantity: 1, category: "consumable", rarity: "raro", effect: "guard", value: 26 },
  { id: "watchblade", name: "Lâmina da Vigília", description: "+2 Força no ataque básico.", lore: "Aço cobreado usado pelos sentinelas que não retornaram das ruínas.", quantity: 1, category: "equipment", rarity: "raro", effect: "none", value: 90, slot: "weapon", bonus: { force: 2 } },
  { id: "lorancloak", name: "Manto de Loran", description: "+2 Defesa e guarda ampliada.", lore: "Tecido com fios rúnicos, ainda coberto pela poeira do primeiro cerco.", quantity: 1, category: "equipment", rarity: "raro", effect: "none", value: 104, slot: "armor", bonus: { defense: 2, guard: .08 } },
  { id: "astralring", name: "Anel de Aster", description: "+3 Arcano ao canalizar magia.", lore: "Um aro de prata escura que responde à presença da mana.", quantity: 0, category: "equipment", rarity: "épico", effect: "none", value: 160, slot: "relic", bonus: { arcane: 3 } },
  { id: "obsidian", name: "Fragmento de Obsidiana", description: "Material de aprimoramento.", lore: "Uma lasca mineral que vibra perto de artefatos antigos.", quantity: 3, category: "material", rarity: "comum", effect: "none", value: 8 },
  { id: "goblinmark", name: "Marca do Batedor", description: "Prova de vitória em Loran.", lore: "Uma moeda tosca marcada com o brasão de uma patrulha goblin.", quantity: 1, category: "material", rarity: "comum", effect: "none", value: 12 },
  { id: "greaterheal", name: "Elixir de Aurora", description: "Restaura 46 de vitalidade.", lore: "Um composto dourado que aquece as mãos antes de fechar as feridas.", quantity: 0, category: "consumable", rarity: "raro", effect: "health", value: 44, effectValue: 46 },
  { id: "moonward", name: "Ampola de Bruma", description: "Ativa uma guarda impenetrável.", lore: "Um vidro frio preenchido com vapor lunar condensado.", quantity: 0, category: "consumable", rarity: "raro", effect: "guard", value: 38 },
  { id: "starlance", name: "Sabre Estelar", description: "+4 Força em ataques físicos.", lore: "Uma lâmina de aço celeste, temperada no fogo de uma estrela cadente.", quantity: 0, category: "equipment", rarity: "épico", effect: "none", value: 150, slot: "weapon", bonus: { force: 4 } },
  { id: "mendercloak", name: "Manto do Remendo", description: "+3 Defesa e guarda ampliada.", lore: "Costurado por sobreviventes de Loran com fios que repelem a sombra.", quantity: 0, category: "equipment", rarity: "raro", effect: "none", value: 118, slot: "armor", bonus: { defense: 3, guard: .1 } },
  { id: "ravenseal", name: "Selo do Corvo", description: "+4 Arcano ao canalizar magia.", lore: "Um talismã negro que murmura rotas entre o éter e a pedra.", quantity: 0, category: "equipment", rarity: "épico", effect: "none", value: 164, slot: "relic", bonus: { arcane: 4 } },
];
const shopStock: StoreItem[] = [
  { id: "healing", price: 18 }, { id: "mana", price: 28 }, { id: "greaterheal", price: 44, featured: true }, { id: "moonward", price: 38 }, { id: "mendercloak", price: 118 }, { id: "starlance", price: 150, featured: true }, { id: "ravenseal", price: 164 },
];
const between = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;
const slotLabel = (slot: Slot) => slot === "weapon" ? "Arma" : slot === "armor" ? "Manto" : "Relíquia";

export default function Home() {
  const [sessionToken, setSessionToken] = useState<string | null>(() => window.localStorage.getItem(sessionStorageKey));
  const [accountNickname, setAccountNickname] = useState("");
  const [hydrated, setHydrated] = useState(false);
  const accountQuery = trpc.rpg.load.useQuery({ sessionToken: sessionToken ?? "" }, { enabled: Boolean(sessionToken), retry: false });
  const saveMutation = trpc.rpg.save.useMutation();
  const previewParams = new URLSearchParams(window.location.search);
  const marketPreview = previewParams.get("market") === "1";
  const restPreview = previewParams.get("rest") === "1";
  const [draft, setDraft] = useState<Draft>(() => marketPreview || restPreview ? { name: "Mira Voss", classId: "guardian", originId: "vigil", appearanceId: "copper" } : { name: "", classId: "guardian", originId: "vigil", appearanceId: "copper" });
  const [started, setStarted] = useState(marketPreview || restPreview);
  const [encounterIndex, setEncounterIndex] = useState(0);
  const [hero, setHero] = useState({ hp: 84, mana: 36, xp: 0, gold: 34 });
  const [enemyHp, setEnemyHp] = useState(encounters[0].hp);
  const [battleState, setBattleState] = useState<BattleState>("active");
  const [turn, setTurn] = useState<TurnOwner>("hero");
  const [motion, setMotion] = useState<CombatMotion>("idle");
  const [guarding, setGuarding] = useState(false);
  const [damage, setDamage] = useState<{ target: TurnOwner; amount: number; critical?: boolean } | null>(null);
  const [intent, setIntent] = useState<Intent>(goblinIntents[0]);
  const [inventory, setInventory] = useState<Item[]>(inventorySeed);
  const [tab, setTab] = useState<"all" | ItemCategory>("all");
  const [selectedId, setSelectedId] = useState<ItemId>("watchblade");
  const [equipped, setEquipped] = useState<Partial<Record<Slot, ItemId>>>({ weapon: "watchblade", armor: "lorancloak" });
  const [logs, setLogs] = useState<Log[]>([]);
  const [marketOpen, setMarketOpen] = useState(marketPreview);
  const [restOpen, setRestOpen] = useState(restPreview);
  const [merchantLine, setMerchantLine] = useState("Vi você nas ruínas. Cobre abre portas, mas só se você souber o que carrega.");

  const current = encounters[encounterIndex];
  const heroClass = classes.find((entry) => entry.id === draft.classId) ?? classes[0];
  const origin = origins.find((entry) => entry.id === draft.originId) ?? origins[0];
  const ClassIcon = heroClass.icon;
  const bonuses = useMemo(() => inventory.filter((item) => item.slot && equipped[item.slot] === item.id).reduce((total, item) => ({ force: (total.force ?? 0) + (item.bonus?.force ?? 0), arcane: (total.arcane ?? 0) + (item.bonus?.arcane ?? 0), defense: (total.defense ?? 0) + (item.bonus?.defense ?? 0), guard: (total.guard ?? 0) + (item.bonus?.guard ?? 0) }), {} as NonNullable<Item["bonus"]>), [inventory, equipped]);
  const stats = [heroClass.stats[0] + (bonuses.force ?? 0), heroClass.stats[1], heroClass.stats[2] + (bonuses.arcane ?? 0), heroClass.stats[3] + (bonuses.defense ?? 0)];
  const guardRate = Math.max(.25, heroClass.guard - (bonuses.guard ?? 0));
  const guardReduction = Math.round((1 - guardRate) * 100);
  const heroHpPct = (hero.hp / heroClass.hp) * 100;
  const manaPct = (hero.mana / heroClass.mana) * 100;
  const enemyPct = (enemyHp / current.hp) * 100;
  const selected = inventory.find((item) => item.id === selectedId) ?? inventory[0];
  const storeItems = shopStock.map((entry) => ({ ...entry, item: inventory.find((item) => item.id === entry.id) ?? inventorySeed.find((item) => item.id === entry.id)! }));
  const visible = inventory.filter((item) => item.quantity > 0 && (tab === "all" || item.category === tab));
  const carried = inventory.reduce((sum, item) => sum + item.quantity, 0);
  const roleLabel = current.role === "mob" ? "MOB" : current.role === "subboss" ? "SUBCHEFE" : "CHEFE";
  const status = heroHpPct > 55 ? "Estável" : heroHpPct > 28 ? "Atenção" : "Crítico";

  useEffect(() => {
    if (!sessionToken) { setHydrated(false); return; }
    if (accountQuery.isError) {
      window.localStorage.removeItem(sessionStorageKey);
      setSessionToken(null);
      setHydrated(false);
      return;
    }
    if (!accountQuery.data || hydrated) return;
    setAccountNickname(accountQuery.data.account.nickname);
    const character = accountQuery.data.character;
    if (character) {
      try {
        const saved = JSON.parse(character.stateJson) as SavedGame;
        if (saved.draft && saved.hero && Array.isArray(saved.inventory)) {
          setDraft(saved.draft); setStarted(saved.started); setEncounterIndex(saved.encounterIndex); setHero(saved.hero);
          setEnemyHp(saved.enemyHp); setBattleState(saved.battleState); setTurn(saved.turn); setInventory(saved.inventory);
          setSelectedId(saved.selectedId); setEquipped(saved.equipped); setLogs(saved.logs ?? []); setMerchantLine(saved.merchantLine ?? merchantLine);
          const restoredEncounter = encounters[saved.encounterIndex] ?? encounters[0];
          setIntent(restoredEncounter.intents.find((entry) => entry.id === saved.intentId) ?? restoredEncounter.intents[0]);
        }
      } catch { /* Fichas de versões antigas iniciam uma nova campanha sem interromper a conta. */ }
    }
    setHydrated(true);
  }, [accountQuery.data, accountQuery.isError, hydrated, sessionToken]);

  const savePayload = useMemo(() => JSON.stringify({ draft, started, encounterIndex, hero, enemyHp, battleState, turn, intentId: intent.id, inventory, selectedId, equipped, logs, merchantLine } satisfies SavedGame), [draft, started, encounterIndex, hero, enemyHp, battleState, turn, intent.id, inventory, selectedId, equipped, logs, merchantLine]);

  useEffect(() => {
    if (!sessionToken || !hydrated || !started || draft.name.trim().length < 2) return;
    const timer = window.setTimeout(() => {
      saveMutation.mutate({ sessionToken, characterName: draft.name.trim(), classId: draft.classId, originId: draft.originId, appearanceId: draft.appearanceId, stateJson: savePayload });
    }, 650);
    return () => window.clearTimeout(timer);
  }, [draft, hydrated, savePayload, sessionToken, started]);

  const note = (actor: string, message: string, tone: Log["tone"]) => setLogs((currentLogs) => [{ id: Date.now(), actor, message, tone }, ...currentLogs].slice(0, 7));
  const showEffect = (nextMotion: CombatMotion, target: TurnOwner, amount?: number, critical = false) => { setMotion(nextMotion); setDamage(amount ? { target, amount, critical } : null); window.setTimeout(() => setMotion("idle"), 720); window.setTimeout(() => setDamage(null), 820); };
  const grant = (id: ItemId, quantity: number) => setInventory((items) => items.map((item) => item.id === id ? { ...item, quantity: item.quantity + quantity } : item));
  const switchIntent = () => setIntent(current.intents[between(0, current.intents.length - 1)]);

  const completeVictory = () => { setBattleState("victory"); setRestOpen(false); setHero((currentHero) => ({ ...currentHero, xp: currentHero.xp + current.xp, gold: currentHero.gold + current.gold })); grant(current.reward.id, current.reward.quantity); note("VITÓRIA", `${current.name} caiu. Você recebe ${current.xp} XP, ${current.gold} cobre e ${current.reward.label}.`, "system"); };
  const damageEnemy = (amount: number, label: string, nextMotion: CombatMotion, critical = false) => { const next = Math.max(0, enemyHp - amount); setEnemyHp(next); showEffect(nextMotion, "enemy", amount, critical); note(draft.name.toUpperCase(), `${label} e causa ${amount}${critical ? " de dano crítico" : " de dano"} a ${current.name}.`, "hero"); if (!next) completeVictory(); else queueEnemy(); };
  const queueEnemy = (protectedTurn = false) => { const planned = intent; setTurn("enemy"); window.setTimeout(() => { const raw = between(planned.min, planned.max); const taken = protectedTurn ? Math.ceil(raw * guardRate) : Math.max(1, raw - Math.floor((bonuses.defense ?? 0) / 2)); const nextHp = Math.max(0, hero.hp - taken); setHero((currentHero) => ({ ...currentHero, hp: nextHp })); showEffect("enemy-attack", "hero", taken); setGuarding(false); if (!nextHp) { setBattleState("defeat"); note("DERROTA", `${draft.name} perde as forças diante de ${current.name}.`, "enemy"); return; } note(current.name.toUpperCase(), `${planned.label} causa ${taken} de dano${protectedTurn ? " reduzido pela guarda" : ""}.`, "enemy"); window.setTimeout(() => { switchIntent(); setTurn("hero"); }, 760); }, 650); };
  const basicAttack = () => { if (battleState !== "active" || turn !== "hero") return; const crit = Math.random() < heroClass.critical; const base = draft.classId === "arcanist" ? between(11, 17) : between(12, 18); damageEnemy((crit ? Math.round(base * 1.65) : base) + (bonuses.force ?? 0), heroClass.basic, draft.classId === "arcanist" ? "hero-magic" : "hero-weapon", crit); };
  const special = () => { if (battleState !== "active" || turn !== "hero") return; if (hero.mana < 10) { note("SISTEMA", "Mana insuficiente para a habilidade especial.", "system"); return; } setHero((currentHero) => ({ ...currentHero, mana: currentHero.mana - 10 })); damageEnemy(between(20, 28) + Math.ceil((bonuses.arcane ?? 0) / 2), heroClass.special, "hero-magic"); };
  const defend = () => { if (battleState !== "active" || turn !== "hero") return; setGuarding(true); showEffect("hero-guard", "hero"); note(draft.name.toUpperCase(), `Ergue a guarda e reduz ${guardReduction}% do próximo dano.`, "hero"); queueEnemy(true); };
  const useItem = (item: Item) => { if (item.category !== "consumable" || item.quantity <= 0 || battleState !== "active" || turn !== "hero") return; if (item.effect === "health" && hero.hp === heroClass.hp) return note("SISTEMA", "A vitalidade já está completa.", "system"); if (item.effect === "mana" && hero.mana === heroClass.mana) return note("SISTEMA", "A mana já está completa.", "system"); if (item.quantity === 1 && selectedId === item.id) setSelectedId("healing"); setInventory((items) => items.map((entry) => entry.id === item.id ? { ...entry, quantity: entry.quantity - 1 } : entry)); if (item.effect === "health") { const restored = Math.min(item.effectValue ?? 0, heroClass.hp - hero.hp); setHero((currentHero) => ({ ...currentHero, hp: Math.min(heroClass.hp, currentHero.hp + restored) })); note(draft.name.toUpperCase(), `Usa ${item.name} e recupera ${restored} de vitalidade.`, "hero"); queueEnemy(false); return; } if (item.effect === "mana") { const restored = Math.min(item.effectValue ?? 0, heroClass.mana - hero.mana); setHero((currentHero) => ({ ...currentHero, mana: Math.min(heroClass.mana, currentHero.mana + restored) })); note(draft.name.toUpperCase(), `Usa ${item.name} e recupera ${restored} de mana.`, "hero"); queueEnemy(false); return; } if (item.effect === "guard") { setGuarding(true); note(draft.name.toUpperCase(), "Ativa o Selo de Guarda.", "hero"); queueEnemy(true); return; } damageEnemy(item.effectValue ?? 0, `Arremessa ${item.name}`, "hero-magic"); };
  const equip = (item: Item) => { if (!item.slot) return; const wasEquipped = equipped[item.slot] === item.id; setEquipped((currentEquipped) => ({ ...currentEquipped, [item.slot!]: wasEquipped ? undefined : item.id })); note("EQUIPAMENTO", wasEquipped ? `${item.name} voltou à mochila.` : `${item.name} foi equipado em ${slotLabel(item.slot)}.`, "system"); };
  const buy = (entry: StoreItem) => { const item = inventory.find((currentItem) => currentItem.id === entry.id); if (!item) return; if (hero.gold < entry.price) { setMerchantLine("Cobre insuficiente. Vença mais criaturas e a banca continuará aberta."); note("MERCADO", `Faltam ${entry.price - hero.gold} cobre para ${item.name}.`, "system"); return; } if (item.category === "equipment" && item.quantity > 0) { setMerchantLine("Você já possui essa peça. Melhor guardar o cobre para uma relíquia futura."); note("MERCADO", `${item.name} já está na sua mochila.`, "system"); return; } setHero((currentHero) => ({ ...currentHero, gold: currentHero.gold - entry.price })); setInventory((items) => items.map((currentItem) => currentItem.id === entry.id ? { ...currentItem, quantity: currentItem.quantity + 1 } : currentItem)); setSelectedId(entry.id); setMerchantLine(`${item.name} é sua. Use, equipe ou guarde como preferir.`); note("MERCADO", `${item.name} foi comprado por ${entry.price} cobre e enviado ao inventário.`, "system"); };
  const startEncounter = (nextIndex: number) => { const next = encounters[nextIndex]; setEncounterIndex(nextIndex); setEnemyHp(next.hp); setHero((currentHero) => ({ ...currentHero, hp: battleState === "defeat" ? heroClass.hp : Math.min(heroClass.hp, currentHero.hp + 32), mana: Math.min(heroClass.mana, currentHero.mana + 14) })); setBattleState("active"); setTurn("hero"); setMotion("idle"); setGuarding(false); setIntent(next.intents[0]); setRestOpen(false); note("CRONISTA", `${next.name} foi escolhido para o próximo duelo. Você recupera vigor antes de avançar.`, "system"); };
  const begin = () => { if (draft.name.trim().length < 2) return; setHero({ hp: heroClass.hp, mana: heroClass.mana, xp: 0, gold: 34 }); setEncounterIndex(0); setEnemyHp(encounters[0].hp); setIntent(encounters[0].intents[0]); setBattleState("active"); setTurn("hero"); setLogs([{ id: Date.now(), actor: "CRONISTA", message: `${draft.name} chega às Ruínas de Loran, trazendo o legado de ${origin.name}.`, tone: "system" }]); setStarted(true); };

  const signOut = () => { window.localStorage.removeItem(sessionStorageKey); setSessionToken(null); setAccountNickname(""); setHydrated(false); setStarted(false); };

  if (!sessionToken) return <AccountGate onAuthenticated={(token, nickname) => { window.localStorage.setItem(sessionStorageKey, token); setAccountNickname(nickname); setSessionToken(token); }} />;
  if (!hydrated) return <main className="account-shell"><div className="account-card panel-frame"><Sparkles size={28} /><h1>Consultando a crônica</h1><p>Carregando sua conta e sua ficha persistida.</p></div></main>;
  if (!started) return <Creator draft={draft} onChange={setDraft} onBegin={begin} />;

  return <main className="app-shell"><div className="ambient-glow ambient-glow-one" /><div className="ambient-glow ambient-glow-two" />
    <header className="topbar"><Brand /><div className="session-meta"><span className="online-dot" /><span>EXPEDIÇÃO ATIVA</span><span className="session-divider" /><span>RUÍNAS DE LORAN</span><span className="account-badge"><CircleDot size={12} /> {accountNickname}</span><span className={`save-badge ${saveMutation.isPending ? "saving" : ""}`}>{saveMutation.isPending ? "SALVANDO" : "SALVO"}</span><button className="merchant-trigger" onClick={() => setMarketOpen(true)}><ShoppingBag size={13} /> MERCADO</button><button className="edit-hero" onClick={() => setStarted(false)}>EDITAR FICHA</button><button className="edit-hero" onClick={signOut}>SAIR</button></div></header>
    <section className="campaign-banner" style={{ backgroundImage: "linear-gradient(90deg, rgba(10,14,19,.96), rgba(10,14,19,.6)), url('https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/canpYvFLCrjSDjnw.png')" }}><div className="banner-copy"><p className="eyebrow"><Sparkles size={14} /> Campanha de demonstração</p><h1>A ameaça avança.<br /><em>Escolha sua jogada.</em></h1><p className="banner-description">Conduza {draft.name} pelas ruínas, administre recursos e termine a trilha de três encontros.</p></div><div className={`quest-chip role-${current.role}`}><Target size={18} /><div><span>OBJETIVO · {current.role === "mob" ? "MOB" : current.role === "subboss" ? "SUBCHEFE" : "CHEFE"}</span><strong>Derrotar {current.name}</strong></div></div></section>
    {restOpen && <RestCamp currentIndex={encounterIndex} onClose={() => setRestOpen(false)} onMarket={() => setMarketOpen(true)} onStart={startEncounter} />}
    {marketOpen && <Market gold={hero.gold} items={storeItems} line={merchantLine} onClose={() => setMarketOpen(false)} onBuy={buy} />}
    <section className="game-board" aria-label="Mesa de jogo tática">
      <aside className="character-panel panel-frame"><div className="panel-heading"><div><span className="micro-label">PERSONAGEM</span><h2>{draft.name}</h2></div><span className="level-mark">NV. 01</span></div><div className="character-identity"><div className={`avatar-shell appearance-${draft.appearanceId}`}><ClassIcon size={35} /></div><div><p>{heroClass.name}</p><span>{origin.name}</span></div></div><div className="resource-stack"><ResourceBar icon={<HeartPulse size={15} />} label="Vitalidade" current={hero.hp} total={heroClass.hp} percent={heroHpPct} className="health" /><ResourceBar icon={<WandSparkles size={15} />} label="Mana" current={hero.mana} total={heroClass.mana} percent={manaPct} className="mana" /></div><div className="status-seal"><span className={`seal-pip ${status.toLowerCase()}`} /> <span>Estado: <strong>{status}</strong></span></div><div className="rune-divider"><span>ATRIBUTOS</span></div><div className="stat-grid"><Stat icon={<Sword size={15} />} value={stats[0]} label="Força" /><Stat icon={<Bolt size={15} />} value={stats[1]} label="Agilidade" /><Stat icon={<Sparkles size={15} />} value={stats[2]} label="Arcano" /><Stat icon={<Shield size={15} />} value={stats[3]} label="Defesa" /></div><div className="equipped-summary"><span><ShieldPlus size={13} /> VÍNCULOS ATIVOS</span><p>{Object.values(equipped).filter(Boolean).length}/3 equipamentos</p></div><div className="progress-section"><div className="progress-copy"><span>PROGRESSO DE NÍVEL</span><strong>{hero.xp} / 500 XP</strong></div><div className="thin-progress"><span style={{ width: `${(hero.xp / 500) * 100}%` }} /></div><div className="gold-row"><span><Trophy size={14} /> Recompensas</span><strong>{hero.gold} <small>cobre</small></strong></div></div></aside>
      <section className="battle-panel panel-frame"><div className="battle-topline"><span className={`turn-pill ${battleState === "active" ? "current" : "resolved"}`}><span className="turn-pulse" /> {battleState === "active" ? turn === "hero" ? "SEU TURNO" : "TURNO DO INIMIGO" : battleState === "victory" ? "ENCONTRO VENCIDO" : "EXPEDIÇÃO INTERROMPIDA"}</span><span className={`encounter-code encounter-${current.role}`}>ENCONTRO {encounterIndex + 1} / 03</span></div><div className={`combat-stage duel-stage motion-${motion} ${current.role}`}><div className="duel-lane" /><Combatant side="hero" name={draft.name} subtitle={heroClass.name} hp={hero.hp} maxHp={heroClass.hp} percent={heroHpPct} portrait={portraits[draft.classId]} attackPortrait={attackPortraits[draft.classId]} icon={<ClassIcon size={15} />} active={turn === "hero" && battleState === "active"} hit={damage?.target === "hero"} damage={damage?.target === "hero" ? damage : null} guarding={guarding} guardReduction={guardReduction} /><div className="duel-center"><span className="duel-vs">VS</span><span className={`turn-announcer ${turn}`}>{battleState === "active" ? turn === "hero" ? "ESCOLHA UMA AÇÃO" : "O INIMIGO SE MOVE" : battleState === "victory" ? "VITÓRIA" : "DERROTA"}</span>{battleState === "active" && <div className={`enemy-intent ${intent.id}`}><span><Eye size={11} /> PRÓXIMO GOLPE</span><strong>{intent.label}</strong><small>{intent.description} · {intent.min}–{intent.max}</small></div>}</div><Combatant side="enemy" name={current.name} subtitle={current.description} hp={enemyHp} maxHp={current.hp} percent={enemyPct} portrait={current.portrait} attackPortrait={current.attackPortrait} icon={<Crosshair size={15} />} active={turn === "enemy" && battleState === "active"} hit={damage?.target === "enemy"} damage={damage?.target === "enemy" ? damage : null} role={current.role} />{battleState !== "active" && <div className={`battle-resolution ${battleState}`}><Trophy size={28} /><div><strong>{battleState === "victory" ? "A trilha está livre" : "É hora de recuar"}</strong><span>{battleState === "victory" ? `${current.reward.label} foi adicionado ao inventário. Escolha seu próximo passo.` : "Recupere-se e escolha quando voltar a lutar."}</span></div><button onClick={() => setRestOpen(true)}>Ponto de descanso<ChevronRight size={16} /></button></div>}</div><div className="action-deck"><div className="action-header"><div><span className="micro-label">AÇÕES DE COMBATE</span><p>{battleState !== "active" ? "A luta terminou. Você decide quando continuará." : turn === "enemy" ? `${current.name} prepara sua resposta.` : guarding ? "Guarda reforçada até o próximo ataque." : "A decisão é sua. Cada ação encerra o turno."}</p></div><span className="action-hint">{turn === "hero" ? heroClass.passive : "aguarde"}</span></div><div className="action-grid"><Action onClick={basicAttack} disabled={battleState !== "active" || turn !== "hero"} icon={draft.classId === "arcanist" ? <Sparkles size={19} /> : <Sword size={19} />} title={heroClass.basic} detail={`12–18 dano · +${bonuses.force ?? 0} equip.`} variant="copper" hotkey="A" /><Action onClick={special} disabled={battleState !== "active" || turn !== "hero"} icon={<Zap size={19} />} title={heroClass.special} detail={`20–28 dano · 10 mana`} variant="arcane" hotkey="R" /><Action onClick={defend} disabled={battleState !== "active" || turn !== "hero"} icon={<Shield size={19} />} title="Postura de guarda" detail={`Reduz ${guardReduction}% do próximo dano`} variant="slate" hotkey="D" /></div></div></section>
      <aside className="utility-column"><Inventory inventory={inventory} visible={visible} selected={selected} selectedId={selectedId} tab={tab} equipped={equipped} carried={carried} canAct={battleState === "active" && turn === "hero"} onTab={setTab} onSelect={setSelectedId} onUse={useItem} onEquip={equip} /><section className="log-panel panel-frame"><div className="panel-heading compact"><div><span className="micro-label">REGISTRO</span><h2>Crônica da batalha</h2></div><History size={18} /></div><div className="battle-log" aria-live="polite">{logs.map((entry) => <article className={`log-entry ${entry.tone}`} key={entry.id}><span>{entry.actor}</span><p>{entry.message}</p></article>)}</div></section></aside>
    </section><footer className="bottom-note"><BookOpen size={15} /> <span><strong>Dica de campanha:</strong> equipamentos alteram seus atributos e chefes liberam relíquias de alto impacto.</span></footer>
  </main>;
}

function AccountGate({ onAuthenticated }: { onAuthenticated: (token: string, nickname: string) => void }) {
  const [mode, setMode] = useState<"register" | "login">("register");
  const [nickname, setNickname] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");
  const register = trpc.rpg.register.useMutation();
  const login = trpc.rpg.login.useMutation();
  const busy = register.isPending || login.isPending;
  const submit = () => {
    setMessage("");
    const mutation = mode === "register" ? register : login;
    mutation.mutate({ nickname, password }, {
      onSuccess: (account) => onAuthenticated(account.sessionToken, account.nickname),
      onError: (error) => setMessage(error.message),
    });
  };
  return <main className="account-shell"><div className="account-glow" /><header className="account-topbar"><Brand /><span className="creator-tag"><ShieldCheck size={14} /> CRÔNICA PERSISTENTE</span></header><section className="account-layout"><aside className="account-story"><p className="eyebrow"><Archive size={14} /> Arquivo de Loran</p><h1>Uma conta.<br /><em>Uma crônica que permanece.</em></h1><p>Crie um acesso para guardar personagem, ouro, inventário, equipamentos e escolhas da expedição. Sua senha é protegida antes de ser salva.</p><div className="account-perks"><span><ShieldCheck size={15} /> Ficha vinculada ao seu nick</span><span><Backpack size={15} /> Inventário e equipamentos preservados</span><span><History size={15} /> Campanha retomada do último ponto</span></div></aside><section className="account-card panel-frame"><div className="account-tabs"><button className={mode === "register" ? "active" : ""} onClick={() => { setMode("register"); setMessage(""); }}>Criar conta</button><button className={mode === "login" ? "active" : ""} onClick={() => { setMode("login"); setMessage(""); }}>Entrar</button></div><div className="account-form"><span className="micro-label">{mode === "register" ? "NOVA FICHA" : "RETORNO ÀS RUÍNAS"}</span><h2>{mode === "register" ? "Registre sua crônica" : "Sua campanha espera"}</h2><p>{mode === "register" ? "Escolha um nick e uma senha para iniciar uma ficha que poderá continuar depois." : "Entre com o nick e a senha usados para guardar sua última expedição."}</p><label><span>NICK</span><input autoComplete="username" value={nickname} onChange={(event) => setNickname(event.target.value.replace(/\s/g, "").slice(0, 32))} placeholder="Ex.: mira_voss" /></label><label><span>SENHA</span><input autoComplete={mode === "register" ? "new-password" : "current-password"} type="password" value={password} onChange={(event) => setPassword(event.target.value.slice(0, 72))} placeholder="Mínimo de 6 caracteres" onKeyDown={(event) => event.key === "Enter" && submit()} /></label>{message && <p className="account-error">{message}</p>}<button className="account-submit" disabled={busy || nickname.length < 3 || password.length < 6} onClick={submit}>{busy ? "Consultando arquivo…" : mode === "register" ? "Criar conta e forjar ficha" : "Entrar na campanha"}<ChevronRight size={17} /></button><small className="account-security"><Shield size={13} /> A senha não é guardada em texto puro.</small></div></section></section></main>;
}

function Brand() { return <div className="brand-lockup" aria-label="RPG Scplt"><img src="https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/IcgAumTmtETsvhpT.png" alt="Escudo rúnico de RPG Scplt" className="brand-emblem" /><div><span className="brand-title">RPG SCPLT</span><span className="brand-subtitle">CRÔNICAS DE OBSIDIANA</span></div></div>; }
function ResourceBar({ icon, label, current, total, percent, className }: { icon: React.ReactNode; label: string; current: number; total: number; percent: number; className: string }) { return <div className={`resource-bar ${className}`}><div className="resource-label"><span>{icon}{label}</span><strong>{current}<small>/{total}</small></strong></div><div className="resource-track"><span style={{ width: `${Math.max(0, percent)}%` }} /></div></div>; }
function Stat({ icon, value, label }: { icon: React.ReactNode; value: number; label: string }) { return <div className="stat-box"><span>{icon}</span><strong>{value}</strong><small>{label}</small></div>; }
function Action({ onClick, disabled, icon, title, detail, variant, hotkey }: { onClick: () => void; disabled: boolean; icon: React.ReactNode; title: string; detail: string; variant: string; hotkey: string }) { return <button className={`combat-action ${variant}`} disabled={disabled} onClick={onClick}><span className="action-icon">{icon}</span><span className="action-content"><strong>{title}</strong><small>{detail}</small></span><kbd>{hotkey}</kbd></button>; }

function Combatant({ side, name, subtitle, hp, maxHp, percent, portrait, attackPortrait, icon, active, hit, damage, guarding, guardReduction, role }: { side: "hero" | "enemy"; name: string; subtitle: string; hp: number; maxHp: number; percent: number; portrait: string; attackPortrait: string; icon: React.ReactNode; active: boolean; hit: boolean; damage: { target: TurnOwner; amount: number; critical?: boolean } | null; guarding?: boolean; guardReduction?: number; role?: "mob" | "subboss" | "boss" }) { const enemy = side === "enemy"; return <div className={`combatant ${enemy ? "npc-combatant" : "hero-combatant"} ${active ? "turn-active" : ""} ${hit ? "taking-hit" : ""} role-${role ?? "hero"}`}><div className={`combatant-data ${enemy ? "enemy-data" : "hero-data"}`}><span className={`combatant-tag ${enemy ? "threat-marker" : ""}`}>{icon} {enemy ? role === "boss" ? "CHEFE" : role === "subboss" ? "SUBCHEFE" : "AMEAÇA 02" : "VOCÊ"}</span><h2>{name}</h2><p>{subtitle}</p><ResourceBar icon={<HeartPulse size={14} />} label="Vitalidade" current={hp} total={maxHp} percent={percent} className={enemy ? "enemy" : "health"} /></div><div className={`combatant-art ${enemy ? "enemy-art" : "hero-art"}`}><img className={`combat-pose idle-pose ${hp === 0 ? "defeated" : ""}`} src={portrait} alt={`${name} em posição de combate`} /><img className="combat-pose attack-pose" src={attackPortrait} alt="" aria-hidden="true" />{enemy ? <span className="enemy-weapon-arc" /> : <><span className="weapon-arc" /><span className="spell-projectile" /></>}<div className={enemy ? "enemy-badge" : "character-sigil"}>{icon}</div></div><span className="impact-burst" aria-hidden="true" />{damage && <span className={`damage-float ${enemy ? "enemy-damage" : "hero-damage"} ${damage.critical ? "critical" : ""}`}>{damage.critical ? "CRÍTICO " : ""}−{damage.amount}</span>}{guarding && <span className="guard-float"><Shield size={15} /> GUARDA · {guardReduction}%</span>}</div>; }

function iconFor(item: Item) { if (item.category === "material") return item.id === "obsidian" ? <Gem size={17} /> : <CircleDot size={17} />; if (item.category === "equipment") return item.slot === "weapon" ? <Sword size={17} /> : item.slot === "armor" ? <ShieldPlus size={17} /> : <Gem size={17} />; return item.effect === "health" ? <Droplets size={17} /> : item.effect === "mana" ? <Sparkles size={17} /> : item.effect === "guard" ? <Shield size={17} /> : <Zap size={17} />; }
function Inventory({ inventory, visible, selected, selectedId, tab, equipped, carried, canAct, onTab, onSelect, onUse, onEquip }: { inventory: Item[]; visible: Item[]; selected: Item; selectedId: ItemId; tab: "all" | ItemCategory; equipped: Partial<Record<Slot, ItemId>>; carried: number; canAct: boolean; onTab: (tab: "all" | ItemCategory) => void; onSelect: (id: ItemId) => void; onUse: (item: Item) => void; onEquip: (item: Item) => void }) { const tabs: { id: "all" | ItemCategory; label: string; icon: React.ReactNode }[] = [{ id: "all", label: "Tudo", icon: <PackageOpen size={13} /> }, { id: "consumable", label: "Uso", icon: <Droplets size={13} /> }, { id: "equipment", label: "Equip.", icon: <ShieldPlus size={13} /> }, { id: "material", label: "Materiais", icon: <Archive size={13} /> }]; const equippedNow = selected.slot ? equipped[selected.slot] === selected.id : false; return <section className="inventory-panel inventory-upgraded panel-frame"><div className="panel-heading compact"><div><span className="micro-label">MOCHILA DE CAMPO</span><h2>Inventário</h2></div><span className="carry-count"><Backpack size={14} /> {carried}<small>/18</small></span></div><div className="inventory-tabs">{tabs.map((entry) => <button key={entry.id} className={tab === entry.id ? "active" : ""} onClick={() => onTab(entry.id)}>{entry.icon}<span>{entry.label}</span></button>)}</div><div className="equipment-rack"><div><span>EQUIPADO</span><small>{Object.values(equipped).filter(Boolean).length}/3 vínculos</small></div><section>{(["weapon", "armor", "relic"] as Slot[]).map((slot) => { const item = inventory.find((entry) => entry.id === equipped[slot]); return <button key={slot} className={item ? "equipped-slot" : "empty-slot"} title={item?.name ?? `${slotLabel(slot)} vazio`} onClick={() => item && onSelect(item.id)}>{item ? iconFor(item) : <CircleDot size={15} />}<small>{slotLabel(slot)}</small></button>; })}</section></div><div className="inventory-list upgraded-list">{visible.map((item) => <button key={item.id} className={`inventory-card ${selectedId === item.id ? "selected" : ""} rarity-${item.rarity}`} onClick={() => onSelect(item.id)}><span className="item-icon">{iconFor(item)}</span><div><span className="item-title"><strong>{item.name}</strong>{item.slot && equipped[item.slot] === item.id && <em>Em uso</em>}</span><small>{item.description}</small></div><span className="item-qty">{item.category === "equipment" ? item.rarity : `×${item.quantity}`}</span></button>)}</div><div className={`item-inspector rarity-${selected.rarity}`}><div className="inspector-heading"><span className="item-icon">{iconFor(selected)}</span><div><span>{selected.rarity} · {selected.slot ? slotLabel(selected.slot) : selected.category === "consumable" ? "Consumível" : "Material"}</span><h3>{selected.name}</h3></div></div><p>{selected.lore}</p><div className="item-effect"><span>EFEITO</span><strong>{selected.description}</strong></div><div className="inspector-footer"><small><Gem size={12} /> {selected.value} cobre</small>{selected.category === "consumable" ? <button disabled={!canAct || selected.quantity === 0} onClick={() => onUse(selected)}>Usar <span>×{selected.quantity}</span></button> : selected.slot ? <button onClick={() => onEquip(selected)}>{equippedNow ? "Guardar" : "Equipar"}</button> : <span className="material-lock"><Archive size={12} /> Aprimoramento</span>}</div></div></section>; }

function Market({ gold, items, line, onClose, onBuy }: { gold: number; items: Array<StoreItem & { item: Item }>; line: string; onClose: () => void; onBuy: (entry: StoreItem) => void }) { const [selectedId, setSelectedId] = useState<ItemId>(items[0]?.id ?? "healing"); const selected = items.find((entry) => entry.id === selectedId) ?? items[0]; if (!selected) return null; return <div className="market-overlay" role="presentation" onMouseDown={onClose}><section className="market-modal panel-frame" role="dialog" aria-modal="true" aria-label="Mercado de Oren Vale" onMouseDown={(event) => event.stopPropagation()}><button className="market-close" onClick={onClose} aria-label="Fechar mercado"><X size={18} /></button><aside className="merchant-panel"><div className="merchant-portrait-wrap"><img src="/manus-storage/loran-merchant_05dd582f.png" alt="Oren Vale, mercador das ruínas" /><span className="merchant-sigil"><ShoppingBag size={15} /> MERCADOR</span></div><div className="merchant-copy"><p className="micro-label"><MessageCircle size={13} /> OREN VALE</p><h2>“Toda ruína tem um preço.”</h2><p>{line}</p></div><div className="merchant-wallet"><Coins size={16} /><span>SEU SALDO</span><strong>{gold} <small>cobre</small></strong></div></aside><section className="market-stock"><header className="market-heading"><div><span className="micro-label">BARRACA DE CAMPO</span><h2>Artefatos para a expedição</h2><p>Compras chegam direto à mochila. Você decide quando usar ou equipar.</p></div><span className="market-count">{items.length} ofertas</span></header><div className="market-layout"><div className="shop-grid">{items.map((entry) => <button key={entry.id} className={`shop-card rarity-${entry.item.rarity} ${selectedId === entry.id ? "selected" : ""} ${entry.featured ? "featured" : ""}`} onClick={() => setSelectedId(entry.id)}><span className="shop-icon">{iconFor(entry.item)}</span><div><strong>{entry.item.name}</strong><small>{entry.item.description}</small></div>{entry.featured && <em>ESCOLHA DE OREN</em>}<span className="shop-price"><Coins size={12} /> {entry.price}</span></button>)}</div><aside className={`shop-inspector rarity-${selected.item.rarity}`}><span className="shop-icon">{iconFor(selected.item)}</span><span className="item-rarity">{selected.item.rarity} · {selected.item.slot ? slotLabel(selected.item.slot) : "Consumível"}</span><h3>{selected.item.name}</h3><p>{selected.item.lore}</p><div className="shop-effect"><span>EFEITO</span><strong>{selected.item.description}</strong></div><button className="buy-button" disabled={gold < selected.price} onClick={() => onBuy(selected)}><ShoppingBag size={15} /> Comprar por <strong>{selected.price}</strong><Coins size={13} /></button>{gold < selected.price && <small className="shortage">Faltam {selected.price - gold} cobre.</small>}</aside></div></section></section></div>; }

function RestCamp({ currentIndex, onClose, onMarket, onStart }: { currentIndex: number; onClose: () => void; onMarket: () => void; onStart: (index: number) => void }) { const [choosing, setChoosing] = useState(false); const role = (entry: Encounter) => entry.role === "mob" ? "MOB" : entry.role === "subboss" ? "SUBCHEFE" : "CHEFE"; return <div className="rest-overlay" role="presentation" onMouseDown={onClose}><section className="rest-modal panel-frame" role="dialog" aria-modal="true" aria-label="Ponto de descanso" onMouseDown={(event) => event.stopPropagation()}><button className="rest-close" onClick={onClose} aria-label="Fechar ponto de descanso"><X size={18} /></button><header><span className="micro-label"><Sparkles size={13} /> PONTO DE DESCANSO</span><h2>A expedição espera por você.</h2><p>Você venceu o encontro {currentIndex + 1}. Organize a mochila, visite Oren Vale ou escolha o próximo adversário quando estiver pronto.</p></header>{!choosing ? <div className="rest-actions"><button className="rest-choice merchant" onClick={onMarket}><span><ShoppingBag size={21} /></span><div><strong>Visitar o mercado</strong><small>Comprar recursos e equipamentos com seu cobre.</small></div><ChevronRight size={16} /></button><button className="rest-choice encounter" onClick={() => setChoosing(true)}><span><Crosshair size={21} /></span><div><strong>Escolher próximo inimigo</strong><small>Veja a dificuldade e a recompensa antes de começar.</small></div><ChevronRight size={16} /></button><button className="rest-choice pause" onClick={onClose}><span><ScrollText size={21} /></span><div><strong>Continuar depois</strong><small>Nenhuma batalha começará até sua escolha.</small></div><ChevronRight size={16} /></button></div> : <div className="encounter-selection"><div className="selection-heading"><button onClick={() => setChoosing(false)}>Voltar</button><span>ESCOLHA UM ALVO</span></div><div className="encounter-cards">{encounters.map((entry, index) => <button key={entry.name} className={`encounter-card role-${entry.role}`} onClick={() => onStart(index)}><span className="encounter-role"><Crosshair size={13} /> {role(entry)}</span><strong>{entry.name}</strong><small>{entry.description}</small><div><span><HeartPulse size={12} /> {entry.hp} VIT</span><span><Trophy size={12} /> {entry.gold} cobre</span></div><em>{index === currentIndex ? "Revanche" : "Iniciar duelo"}</em></button>)}</div></div>}</section></div>; }

function Creator({ draft, onChange, onBegin }: { draft: Draft; onChange: (draft: Draft) => void; onBegin: () => void }) { const [step, setStep] = useState(1); const heroClass = classes.find((entry) => entry.id === draft.classId) ?? classes[0]; const origin = origins.find((entry) => entry.id === draft.originId) ?? origins[0]; const appearance = appearances.find((entry) => entry.id === draft.appearanceId) ?? appearances[0]; const Icon = heroClass.icon; return <main className="creator-shell" style={{ backgroundImage: "linear-gradient(90deg, rgba(8,12,16,.98), rgba(8,12,16,.55)), url('https://files.manuscdn.com/user_upload_by_module/session_file/310419663030079711/canpYvFLCrjSDjnw.png')" }}><div className="creator-noise" /><header className="creator-topbar"><Brand /><span className="creator-tag"><Gem size={14} /> FORJE SUA FICHA</span></header><section className="creator-layout"><aside className="creator-intro"><p className="eyebrow"><Sparkles size={14} /> Prólogo da expedição</p><h1>Antes da ruína,<br /><em>escolha quem entra.</em></h1><p>Seu nome, origem e senda definem o primeiro registro da campanha e moldam os atributos com que você enfrentará Loran.</p><div className="creator-steps">{["Identidade", "Senda", "Aspecto"].map((label, index) => <div key={label} className={step === index + 1 ? "active" : step > index + 1 ? "completed" : ""}><span>{String(index + 1).padStart(2, "0")}</span>{label}</div>)}</div></aside><section className="creator-card panel-frame"><div className="creator-progress"><span>ETAPA {step} DE 3</span><div><i style={{ width: `${(step / 3) * 100}%` }} /></div></div>{step === 1 && <div className="creation-step"><span className="micro-label">IDENTIDADE</span><h2>Qual será seu nome na crônica?</h2><p>Escolha uma origem para dar contexto à sua jornada nas Ruínas de Loran.</p><label className="character-name"><span>NOME DO PERSONAGEM</span><input value={draft.name} onChange={(event) => onChange({ ...draft, name: event.target.value.slice(0, 22) })} placeholder="Ex.: Arin Valcrest" autoFocus /></label><div className="choice-list origin-list">{origins.map((entry) => <button key={entry.id} className={`choice-card ${draft.originId === entry.id ? "selected" : ""}`} onClick={() => onChange({ ...draft, originId: entry.id })}><span><entry.icon size={20} /></span><div><strong>{entry.name}</strong><small>{entry.desc}</small></div><i /></button>)}</div></div>}{step === 2 && <div className="creation-step"><span className="micro-label">SENDA</span><h2>Como você enfrenta o desconhecido?</h2><p>A classe selecionada define seus atributos iniciais e recursos de combate.</p><div className="class-choice-list">{classes.map((entry) => <button key={entry.id} className={`class-choice ${draft.classId === entry.id ? "selected" : ""}`} onClick={() => onChange({ ...draft, classId: entry.id })}><span className="class-icon"><entry.icon size={24} /></span><div><strong>{entry.name}</strong><small>{entry.summary}</small><p>{entry.desc}</p></div><section><b>{entry.hp}</b><span>VIT</span><b>{entry.mana}</b><span>MAN</span></section></button>)}</div></div>}{step ===3 && <div className="creation-step"><span className="micro-label">ASPECTO</span><h2>Deixe sua marca na vigília.</h2><p>Defina a assinatura cromática que acompanhará sua ficha e confirme a entrada na campanha.</p><div className="appearance-row">{appearances.map((entry) => <button key={entry.id} className={`appearance-choice ${entry.id} ${draft.appearanceId === entry.id ? "selected" : ""}`} onClick={() => onChange({ ...draft, appearanceId: entry.id })}><span><Palette size={18} /></span><strong>{entry.name}</strong><small>{entry.desc}</small></button>)}</div><div className={`hero-preview appearance-${draft.appearanceId}`}><div className="preview-icon"><Icon size={45} /></div><div><span>FICHA PRONTA</span><h3>{draft.name || "Seu nome"}</h3><p>{heroClass.name} · {origin.name}</p></div><em>{appearance.name}</em></div></div>}<div className="creator-actions"><button className="back-button" disabled={step === 1} onClick={() => setStep((current) => current - 1)}>Voltar</button>{step < 3 ? <button className="continue-button" disabled={step === 1 && draft.name.trim().length < 2} onClick={() => setStep((current) => current + 1)}>Continuar <ChevronRight size={16} /></button> : <button className="continue-button" onClick={onBegin}>Iniciar expedição <Sword size={16} /></button>}</div></section></section></main>; }
